mapper.select:
SELECT event_id, title, category_cd, label_cd, start_dt, end_dt, location, description,
       all_day_yn, reg_id, reg_dt, update_id, update_dt
FROM calendar_event
WHERE start_dt < #{rangeEnd}
  AND COALESCE(end_dt, start_dt) >= #{rangeStart}
ORDER BY start_dt

mapper.insert:
